const validateShape=new Ajv2020({strict:false,allErrors:true,coerceTypes:false,useDefaults:false,removeAdditional:false}).compile(shape);
type AdmissionData=typeof inventoryData;
export type InventoryCollection={ id:string;kind:'past_exam';year:number;period:'春期'|'秋期';timeSlot:'午前'|'午後';listedAt:string;subject?:string;publishedOn?:string;questionNumbers:number[];questionPaper:{url:string;sha256:string;byteLength:number;pageCount:number};answerPaper:{url:string;sha256:string;byteLength:number;pageCount:number} };
export const pre2009HardPending=Object.freeze(['source_material_review_pending','source_answer_mapping_pending','source_transcription_pending','source_generation_pending','source_rendering_pending','source_runtime_selection_pending']);
export function assertLegacyEvidenceValues(collections:readonly {id:string}[]):void {
 collections=losslessJSONCopy(collections);
 requireData(collections.length===47&&new Set(collections.map(c=>c.id)).size===47,'IMPORT_ADMISSION_OLD_SCOPE','old47 identities');
 for(const c of collections)requireData(OLD47_VALUES[c.id]===hash(canonicalInventoryJSON(c)),'IMPORT_ADMISSION_OLD_VALUE',c.id);
}
/** Shape, independent identity/provenance, then immutable reviewer root. */
export function validatePre2009InventoryAdmission(input:unknown){
 const copy=losslessJSONCopy(input);requireData(validateShape(copy),'IMPORT_ADMISSION_SHAPE',JSON.stringify(validateShape.errors));
 const d=copy as AdmissionData;
 requireData(new Set(d.collections.map(c=>c.id)).size===20,'IMPORT_ADMISSION_SCOPE','duplicate collection');
 for(const c of d.collections){const expected=EXPECTED_IDENTITIES.find(r=>r.collectionId===c.id);requireData(expected&&c.year===expected.year&&c.period===expected.period&&c.slot===expected.slot&&c.unitKind===expected.unitKind&&canonicalInventoryJSON(c.questionNumbers)===canonicalInventoryJSON(expected.questionNumbers),'IMPORT_ADMISSION_SCOPE',c.id);
  requireData(c.papers.question.role==='qs'&&c.papers.answer.role==='ans','IMPORT_ADMISSION_PROVENANCE','question/answer role positions');
  for(const p of [c.papers.question,c.papers.answer]){const ep=EXPECTED_PAPERS.find(r=>r.collectionId===c.id&&r.role===p.role);requireData(ep,'IMPORT_ADMISSION_PROVENANCE','paper role');parseReviewedArchivePaper(p,ep);}
 }
 requireData(d.boundaries.length===2&&new Set(d.boundaries.map(b=>b.id)).size===2,'IMPORT_ADMISSION_BOUNDARY','two pending boundaries');
 requireData(hash(canonicalInventoryJSON(d))===DATA_VALUE_SHA,'IMPORT_ADMISSION_ROOT','unreviewed data/receipt/observation change');
 const collections:InventoryCollection[]=d.collections.map(c=>{
  const paper=(p:typeof c.papers.question)=>({url:p.selectedArchiveUrl,sha256:p.sha256,byteLength:p.byteLength,pageCount:p.pageCount});
  return {id:c.id,kind:'past_exam',year:c.year,period:c.period==='h'?'春期':'秋期',timeSlot:c.slot==='am'?'午前':'午後',listedAt:c.papers.question.listedYearPage,questionNumbers:[...c.questionNumbers],questionPaper:paper(c.papers.question),answerPaper:paper(c.papers.answer)};
 });
 return freeze({data:d,collections,scope:pre2009InventoryScope});
}
export function validatePre2009AdmissionBytes(raw:Uint8Array){
 requireData(hash(raw)===DATA_BYTE_SHA,'IMPORT_ADMISSION_BYTES','reviewed normalized inventory file');
 return validatePre2009InventoryAdmission(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw)));
}
let admitted:ReturnType<typeof validatePre2009InventoryAdmission>|undefined;
export function readPre2009InventoryAdmission(){
 const raw=fs.readFileSync(new URL('./source-evidence/pre-2009-inventory-admission.json',import.meta.url));
 // Recheck bytes even when reusing a frozen, already validated object.
 requireData(hash(raw)===DATA_BYTE_SHA,'IMPORT_ADMISSION_BYTES','reviewed normalized inventory file');
 if(!admitted)admitted=validatePre2009AdmissionBytes(raw);
 return admitted;
}
